antimony:
model abcd_naive
  compartment cell = 1;
  species Aa in cell = 0;
  species Ba in cell = 0;
  species D in cell = 0;
  u = 1;
  bx11 = 0;
  Atot = 1;
  Btot = 1;
  Ctot = 5;
  k_act = 0.05;
  k_deact = 0.1;
  k_actB = 0.5;
  k_deactB = 0.1;
  k_cat1 = 0.03;
  k_deg = 0.01;
  J1: -> Aa; k_act * u * (Atot - Aa);
  J2: Aa -> ; k_deact * Aa;
  J3: -> Ba; k_actB * (1 - 0.95*bx11) * Aa * (Btot - Ba);
  J4: Ba -> ; k_deactB * Ba;
  J5: -> D; k_cat1 * Ba * (Ctot - D);
  J6: D -> ; k_deg * D;
end
